package net.officefloor.hq.app.peopleimport;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRequest;
import net.officefloor.hq.app.person.PersonRules;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.person.StalePersonException;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Applies each imported line in order. A line naming a person on the sheet updates them as the person form
 *  would — the grade recorded from the sheet's today, their terms and contact set when the line gives them —
 *  recorded as PERSON_EDITED (and its ROLLUP); any other line adds a person as the form would, recorded as
 *  PERSON_ADDED (and its ROLLUP). */
public class SaveImported {
    public void save(@PathVariable("sheetId") String sheetId, @Val ImportInput imported, PersonStore store,
            SheetStore sheets, RollupService rollups, Audit audit, Out<ImportResult> result)
            throws StalePersonException {
        String sheet = sheetId.trim();
        int added = 0;
        int updated = 0;
        for (ImportInput.Line line : imported.lines()) {
            PersonRequest request = line.request();
            Rollup before = rollups.snapshot(sheet);
            if (line.existing() != null) {
                Person person = line.existing();
                if (request.terms() != null) {
                    person.setTerms(Integer.valueOf(request.terms()));
                }
                if (request.contact() != null) {
                    person.setContact(request.contact());
                }
                PersonRules.applyGrade(person, request.grade(), null, sheets.today(sheet));
                if (!store.save(person)) {
                    throw new StalePersonException();
                }
                audit.record("PERSON_EDITED sheet=" + person.getSheetId() + " by=" + request.user() + " name="
                        + person.getName() + " grade=" + person.gradeOn(sheets.today(sheet))
                        + (person.isTermsChanged() ? " terms=" + (person.getTerms() == null ? "" : person.getTerms()) : "")
                        + (person.isContactChanged() ? " contact=" + (person.getContact() == null ? "" : person.getContact()) : ""));
                rollups.record(person.getSheetId(), request.user(), before);
                updated++;
                continue;
            }
            Person person = store.add(sheet, request.name(), request.grade(),
                    request.terms() == null ? null : Integer.valueOf(request.terms()), request.contact());
            audit.record("PERSON_ADDED sheet=" + person.getSheetId() + " by=" + request.user() + " name="
                    + person.getName() + " grade=" + request.grade()
                    + (person.getTerms() == null ? "" : " terms=" + person.getTerms())
                    + (person.getContact() == null ? "" : " contact=" + person.getContact()));
            rollups.record(person.getSheetId(), request.user(), before);
            added++;
        }
        result.set(new ImportResult(added, updated));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Val;

/** Applies an edit: the name, and the form's grade recorded from its from-date (the sheet's today when
 *  blank), keeping the grades already recorded — except that a grade left as the row showed it (the one
 *  in force on the sheet's today) with the from-date blank records nothing. Their own terms are recorded from the terms
 *  from-date, keeping those already recorded (from the beginning of time when blank); the edit changes their terms
 *  when the terms typed differ from those in force on the sheet's today, the ones the editor showed. Their contact and tags
 *  become the form's (none when blank). */
public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person, SheetStore sheets) {
        person.setName(request.name());
        person.setContact(request.contact());
        person.setTags(request.tags());
        Integer shown = person.termsOn(sheets.today(person.getSheetId()));
        PersonRules.applyTerms(person, request.terms(), request.termsFrom());
        person.noteTermsChanged(!java.util.Objects.equals(shown,
                request.terms() == null ? null : Integer.valueOf(request.terms())));
        PersonRules.applyGrade(person, request.grade(), request.gradeFrom(), sheets.today(person.getSheetId()));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Gives each selected person the grade from the from-date, in list order (by their positions),
 *  exactly as the person form's edit would (keeping their name and terms), each recorded as PERSON_EDITED
 *  and then how it moved the sheet's figures. A selected person not on the sheet refuses the whole change; a viewer grades no one (0, nothing stored). */
public class GradePeople {
    public void grade(@PathVariable("sheetId") String sheetId, @Val BulkGradeInput input, PersonStore store,
            SheetStore sheets, RoleStore roles, RollupService rollups, Audit audit, Out<BulkGradeResult> result)
            throws InvalidSheetException, StalePersonException {
        String sheet = sheetId.trim();
        List<Person> selected = new ArrayList<>();
        for (Long id : input.personIds()) {
            Person person = store.find(sheet, id);
            if (person == null) {
                throw new InvalidSheetException("No such person: " + id);
            }
            selected.add(person);
        }
        if (roles.find(sheet, input.user()) == Role.VIEWER) {
            result.set(new BulkGradeResult(0));
            return;
        }
        List<Long> order = store.list(sheet).stream().map(Person::getId).toList();
        selected.sort(Comparator.comparingInt(p -> order.indexOf(p.getId())));
        LocalDate today = sheets.today(sheet);
        for (Person person : selected) {
            Rollup before = rollups.snapshot(sheet);
            PersonRules.applyGrade(person, input.grade(), input.gradeFrom(), today);
            if (!store.save(person)) {
                throw new StalePersonException();
            }
            audit.record("PERSON_EDITED sheet=" + sheet + " by=" + input.user() + " name=" + person.getName()
                    + " grade=" + person.gradeOn(today));
            rollups.record(sheet, input.user(), before);
        }
        result.set(new BulkGradeResult(selected.size()));
    }
}
