import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
import { useAsOf } from '../../session/session';

/** A holiday on the sheet (yyyy-mm-dd). A claim's due-by, fixed when it is added, counts business days
 *  past the weekends and those on the sheet then. */
export type Holiday = { date: string };

/** Under the sheet's key, so loading the sheet again re-reads its holidays. */
export const holidaysKey = (sheet: string) => [...sheetKey(sheet), 'holidays'] as const;

export function useHolidays(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(holidaysKey(sheet), asOf),
    queryFn: () => getJson<Holiday[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/holidays`, asOf)),
    enabled: sheet !== '',
  });
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { claimsKey } from '../claims/claims';
import { type Holiday, holidaysKey, useHolidays } from './holidays';

// The sheet's holidays, and the entry a date is added with. A date already on the list is refused.
function Holidays() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const holidays = useHolidays(sheet);
  const [date, setDate] = useState('');
  const queryClient = useQueryClient();

  const add = useMutation({
    mutationFn: (d: string) =>
      postJson<Holiday>(`/api/sheets/${encodeURIComponent(sheet)}/holidays`, { date: d, user }),
    onSuccess: async () => {
      // A holiday re-fixes the due-by of the claims due on or after it.
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: holidaysKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
      ]);
      setDate('');
    },
  });
  const submit = useSubmitOnce(add);

  return (
    <section data-testid="holidays">
      <h2>Holidays</h2>
      <ul>
        {(holidays.data ?? []).map((h) => (
          <li key={h.date} data-testid={`holiday-row-${h.date}`}>
            {h.date}
          </li>
        ))}
      </ul>
      <form
        data-testid="holiday-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit(date);
        }}
      >
        <input
          data-testid="holiday-date"
          placeholder="Date (yyyy-mm-dd)"
          value={date}
          onChange={(e) => {
            setDate(e.target.value);
            add.reset();
          }}
        />
        <button type="submit" data-testid="holiday-add" disabled={add.isPending}>
          Add holiday
        </button>
        {add.isError && (
          <span data-testid="holiday-error" role="alert">
            {' '}
            {add.error instanceof HttpError && add.error.reason ? `${add.error.reason}.` : 'The holiday was refused.'}
          </span>
        )}
      </form>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 47, Component: Holidays });
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}

